
#[test]fn actual_tigervnc_1_12_sync_flush_provide_is_decoded(){let bytes=include_bytes!("../tigervnc-provide.zlib");assert_eq!(decode(bytes,TEXT).unwrap(),"SERVER_CLIPBOARD_OWNED");}
#[test]fn legacy_finished_zlib_still_decodes(){let wire=provide("owned unicode Ω\nline").unwrap();assert_eq!(decode(&wire[12..],TEXT).unwrap(),"owned unicode Ω\nline");}
#[test]fn malformed_trailing_truncated_and_bomb_are_rejected(){let bytes=include_bytes!("../tigervnc-provide.zlib");for n in 0..bytes.len(){assert!(decode(&bytes[..n],TEXT).is_err(),"accepted truncation {n}");}let mut extra=bytes.to_vec();extra.extend([0,1,0,254,255,b'x',0,0,0,255,255]);assert!(decode(&extra,TEXT).is_err());let mut junk=bytes.to_vec();junk.extend(b"junk");assert!(decode(&junk,TEXT).is_err());let mut corrupt=bytes.to_vec();corrupt[4]^=128;assert!(decode(&corrupt,TEXT).is_err());let text="A".repeat(UTF8_WIRE_LIMIT+1000);let wire=provide(&text).unwrap();assert!(decode(&wire[12..],TEXT).is_err());}
#[test]fn requested_provide_and_policy_gates_are_retained(){let bytes=include_bytes!("../tigervnc-provide.zlib");let mut c=Clipboard::default();let flags=CAPS|TEXT|REQUEST|PROVIDE|NOTIFY;let mut caps=flags.to_be_bytes().to_vec();caps.extend(8192u32.to_be_bytes());c.incoming(&caps,ClipboardPolicy::Bidirectional,false).unwrap();let mut packet=(PROVIDE|TEXT).to_be_bytes().to_vec();packet.extend(bytes);assert!(c.incoming(&packet,ClipboardPolicy::Bidirectional,false).unwrap().text.is_none());c.incoming(&(NOTIFY|TEXT).to_be_bytes(),ClipboardPolicy::Bidirectional,false).unwrap();assert_eq!(c.incoming(&packet,ClipboardPolicy::Bidirectional,false).unwrap().text.as_deref(),Some("SERVER_CLIPBOARD_OWNED"));c.incoming(&(NOTIFY|TEXT).to_be_bytes(),ClipboardPolicy::Disabled,false).unwrap();assert!(c.incoming(&packet,ClipboardPolicy::Disabled,false).unwrap().text.is_none());}
